package io.knowledgebrain.collaboration;
import io.knowledgebrain.contracts.collaboration.discussion.v1.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP",matches=".+")
class DiscussionKafkaIntegrationTest {
 @Test void threadAndReplyCdcBytesAndUnacknowledgedReplay()throws Exception{
  var f=new DiscussionStoreIntegrationTest();f.setup();var v=f.create(f.f.key()).discussion();var reply=f.reply(v.discussionId(),1,f.f.key(),"Shared reply").reply();f.store.state(f.group,f.space,f.study,v.discussionId(),f.f.owner,1,"LOCKED",f.f.trace);f.store.state(f.group,f.space,f.study,v.discussionId(),f.f.owner,2,"OPEN",f.f.trace);f.store.state(f.group,f.space,f.study,v.discussionId(),f.f.owner,3,"RETIRED",f.f.trace);var expected=new HashMap<String,byte[]>();for(var aggregate:List.of(v.discussionId(),reply.replyId()))for(var bytes:f.f.jdbc.queryForList("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,aggregate)){var e=DiscussionEnvelopeV1.parseFrom(bytes);expected.put(e.getEventId(),bytes);}assertEquals(5,expected.size());
  var options=new Properties();options.put("bootstrap.servers",System.getenv("BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP"));options.put("group.id","group-validation-"+UUID.randomUUID());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());options.put("security.protocol","SSL");options.put("ssl.endpoint.identification.algorithm","HTTPS");options.put("ssl.truststore.type","PEM");options.put("ssl.keystore.type","PEM");options.put("ssl.truststore.certificates",Files.readString(Path.of("/group-kafka-test/ca.crt")));options.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/group-kafka-test/user.crt")));options.put("ssl.keystore.key",Files.readString(Path.of("/group-kafka-test/user.key")));
  for(int replay=0;replay<2;replay++){var seen=new HashSet<String>();try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("collaboration.discussion.v1","collaboration.discussion-reply.v1"));long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(seen.size()<5&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofMillis(300))){var e=DiscussionEnvelopeV1.parseFrom(record.value());if(!expected.containsKey(e.getEventId()))continue;assertArrayEquals(expected.get(e.getEventId()),record.value());assertEquals(e.getAggregateId(),record.key());assertEquals(f.f.trace,e.getTraceId());assertEquals(f.space.toString(),e.getSpaceId());if(e.getAggregateType().equals("Discussion")){var p=DiscussionSnapshotV1.parseFrom(e.getPayload());assertEquals(v.discussionId().toString(),p.getDiscussionId());assertEquals("GROUP_MEMBERS",p.getAudience());assertEquals("collaboration.discussion.v1",record.topic());}else{var p=DiscussionReplySnapshotV1.parseFrom(e.getPayload());assertEquals(reply.replyId().toString(),p.getReplyId());assertEquals("GROUP_MEMBERS",p.getAudience());assertEquals("collaboration.discussion-reply.v1",record.topic());}for(var entry:Map.of("trace_id",f.f.trace,"schema_group","collaboration","schema_artifact","discussion-events","schema_version","1").entrySet())assertEquals(entry.getValue(),new String(record.headers().lastHeader(entry.getKey()).value(),StandardCharsets.UTF_8));seen.add(e.getEventId());}}assertEquals(expected.keySet(),seen);}
  System.out.println("PASS collaboration.discussion.v1 five byte-exact discussion/reply snapshots, stable IDs, trace/schema headers and unacknowledged replay");
 }
}
